from collections.abc import Callable, Iterator

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.patch("/assets" + "/{item_id}", response_model=schemas.AssetRead)
    def patch(
        item_id: int, payload: schemas.AssetPatch, db: Session = Depends(get_session)
    ) -> models.Asset:
        row = db.get(models.Asset, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/assets" + "/{item_id}", response_model=schemas.AssetRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Asset:
        row = db.get(models.Asset, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    @router.delete("/assets" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Asset, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    @router.post("/assets", response_model=schemas.AssetRead, status_code=201)
    def create(
        payload: schemas.AssetCreate, db: Session = Depends(get_session)
    ) -> models.Asset:
        row = models.Asset(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/assets", response_model=list[schemas.AssetRead])
    def list_items(
        active: bool | None = None,
        limit: int = Query(default=20, ge=1, le=20),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Asset]:
        stmt = select(models.Asset)
        if active is not None:
            stmt = stmt.where(models.Asset.active == active)
        stmt = stmt.order_by(models.Asset.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    return router

