    router = APIRouter()

    @router.post("/cards", response_model=schemas.CardRead, status_code=201)
    def create(
        payload: schemas.CardCreate, db: Session = Depends(get_session)
    ) -> models.Card:
        row = models.Card(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/cards", response_model=list[schemas.CardRead])
    def list_items(
        published: bool | None = None,
        limit: int = Query(default=20, ge=1, le=75),
