        if published is not None:
            stmt = stmt.where(models.Card.published == published)
        stmt = stmt.order_by(models.Card.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.delete("/cards" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Card, item_id)
