from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.delete("/api/reports" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Report, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    @router.post("/api/reports", response_model=schemas.ReportRead, status_code=201)
    def create(
        payload: schemas.ReportCreate, db: Session = Depends(get_session)
    ) -> models.Report:
        row = models.Report(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/api/reports" + "/{item_id}", response_model=schemas.ReportRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Report:
        row = db.get(models.Report, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    @router.get("/api/reports", response_model=list[schemas.ReportRead])
    def list_items(
        closed: bool | None = None,
        limit: int = Query(default=20, ge=1, le=90),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Report]:
        stmt = select(models.Report)
        if closed is not None:
            stmt = stmt.where(models.Report.closed == closed)
        stmt = stmt.order_by(models.Report.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.patch("/api/reports" + "/{item_id}", response_model=schemas.ReportRead)
    def patch(
        item_id: int, payload: schemas.ReportPatch, db: Session = Depends(get_session)
    ) -> models.Report:
        row = db.get(models.Report, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    return router

