from collections.abc import Callable, Iterator

from datetime import date
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from . import models, schemas


def create_router(get_session: Callable[[], Iterator[Session]]) -> APIRouter:
    router = APIRouter()

    @router.post("/milestones", response_model=schemas.MilestoneRead, status_code=201)
    def create(
        payload: schemas.MilestoneCreate, db: Session = Depends(get_session)
    ) -> models.Milestone:
        row = models.Milestone(**payload.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/milestones" + "/{item_id}", response_model=schemas.MilestoneRead)
    def get(item_id: int, db: Session = Depends(get_session)) -> models.Milestone:
        row = db.get(models.Milestone, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        return row

    @router.delete("/milestones" + "/{item_id}", status_code=204)
    def delete(item_id: int, db: Session = Depends(get_session)) -> None:
        row = db.get(models.Milestone, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        db.delete(row)
        db.commit()

    @router.patch("/milestones" + "/{item_id}", response_model=schemas.MilestoneRead)
    def patch(
        item_id: int, payload: schemas.MilestonePatch, db: Session = Depends(get_session)
    ) -> models.Milestone:
        row = db.get(models.Milestone, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.get("/milestones", response_model=list[schemas.MilestoneRead])
    def list_items(
        resolved: bool | None = None,
        before: date | None = None,
        limit: int = Query(default=20, ge=1, le=30),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Milestone]:
        stmt = select(models.Milestone)
        if resolved is not None:
            stmt = stmt.where(models.Milestone.resolved == resolved)
        if before is not None:
            stmt = stmt.where(models.Milestone.target_on < before)
        stmt = stmt.order_by(models.Milestone.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    return router

