        selected: bool | None = None,
        before: date | None = None,
        limit: int = Query(default=20, ge=1, le=100),
        offset: int = Query(default=0, ge=0),
        db: Session = Depends(get_session),
    ) -> list[models.Entry]:
        stmt = select(models.Entry)
        if selected is not None:
            stmt = stmt.where(models.Entry.selected == selected)
        if before is not None:
            stmt = stmt.where(models.Entry.cutoff_on < before)
        stmt = stmt.order_by(models.Entry.id).limit(limit).offset(offset)
        return list(db.scalars(stmt))

    @router.post("/entries", response_model=schemas.EntryRead, status_code=201)
    def create(
        payload: schemas.EntryCreate, db: Session = Depends(get_session)
    ) -> models.Entry:
