        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
        return row

    @router.delete("/entries" + "/{item_id}", status_code=204)
