    @router.patch("/entries" + "/{item_id}", response_model=schemas.EntryRead)
    def patch(
        item_id: int, payload: schemas.EntryPatch, db: Session = Depends(get_session)
    ) -> models.Entry:
        row = db.get(models.Entry, item_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        for key, value in payload.model_dump(exclude_unset=True).items():
            setattr(row, key, value)
        try:
            db.commit()
        except IntegrityError as exc:
            db.rollback()
            raise HTTPException(status_code=409, detail="conflict") from exc
        db.refresh(row)
