from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class CustomerCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str
    reference: str


class CustomerRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    name: str
    reference: str
    created_at: datetime
    updated_at: datetime


class CustomerPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None
    reference: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "CustomerPatch":
        nullable = {
            "name": False,
            "reference": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class ContactCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str
    email: str | None = None
    phone: str | None = None
    subscribed: bool = False
    external_code: str


class ContactRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    customer_id: int
    name: str
    email: str | None
    phone: str | None
    subscribed: bool
    external_code: str
    created_at: datetime
    updated_at: datetime


class ContactPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None
    email: str | None = None
    phone: str | None = None
    subscribed: bool | None = None
    external_code: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "ContactPatch":
        nullable = {
            "name": False,
            "email": True,
            "phone": True,
            "subscribed": False,
            "external_code": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: CustomerCreate
    children: list[ContactCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: CustomerRead
    children: list[ContactRead]

