from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class CourseCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    code: str
    title: str


class CourseRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    code: str
    title: str
    created_at: datetime
    updated_at: datetime


class CoursePatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    code: str | None = None
    title: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "CoursePatch":
        nullable = {
            "code": False,
            "title": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class LessonCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    title: str
    minutes: int
    published: bool = False
    release_on: date | None = None
    external_code: str


class LessonRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    course_id: int
    title: str
    minutes: int
    published: bool
    release_on: date | None
    external_code: str
    created_at: datetime
    updated_at: datetime


class LessonPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    title: str | None = None
    minutes: int | None = None
    published: bool | None = None
    release_on: date | None = None
    external_code: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "LessonPatch":
        nullable = {
            "title": False,
            "minutes": False,
            "published": False,
            "release_on": True,
            "external_code": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: CourseCreate
    children: list[LessonCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: CourseRead
    children: list[LessonRead]

