    def get_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        return require_child(db, parent_id, child_id)

    @router.post("/documents/with-children", response_model=BatchRead, status_code=201)
    def create_batch(data: BatchCreate, db: Session = Depends(get_session)):
        parent = Parent(**data.parent.model_dump())
        children = []
        try:
            db.add(parent)
            db.flush()
            for item in data.children:
                child = Child(document_id=parent.id, **item.model_dump())
                db.add(child)
                db.flush()
                children.append(child)
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(parent)
        for child in children:
            db.refresh(child)
        return {"parent": parent, "children": children}

    @router.get("/documents/{parent_id}", response_model=ParentRead)
    def get_parent(parent_id: int, db: Session = Depends(get_session)):
        return require_parent(db, parent_id)

    @router.delete("/documents/{parent_id}/reviews/{child_id}", status_code=204)
    def delete_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.patch("/documents/{parent_id}/reviews/{child_id}", response_model=ChildRead)
    def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.get("/documents", response_model=list[ParentRead])
    def list_parent(limIt: int = Query(20, alias="limit", ge=1, le=25), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        statement = select(Parent)
        return list(db.scalars(statement.order_by(Parent.id).limit(limIt).offset(offset)))

    @router.delete("/documents/{parent_id}", status_code=204)
    def delete_parent(parent_id: int, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.get("/documents/{parent_id}/reviews", response_model=list[ChildRead])
    def list_child(parent_id: int, approved: bool | None = None, before: date | None = None, limIt: int = Query(20, alias="limit", ge=1, le=20), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        statement = select(Child).where(Child.document_id == parent_id)
        if approved is not None:
            statement = statement.where(Child.approved == approved)
        if before is not None:
            statement = statement.where(Child.review_by < before)
        return list(db.scalars(statement.order_by(Child.id).limit(limIt).offset(offset)))

    @router.patch("/documents/{parent_id}", response_model=ParentRead)
    def patch_parent(parent_id: int, data: ParentPatch, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    return router

